'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var degenerate = require( '@stdlib/stats/base/dists/degenerate/logcdf' ).factory;
var erfcx = require( '@stdlib/math/base/special/erfcx' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var erfc = require( '@stdlib/math/base/special/erfc' );
var exp = require( '@stdlib/math/base/special/exp' );
var ln = require( '@stdlib/math/base/special/ln' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Returns a function for evaluating the natural logarithm of the cumulative distribution function (CDF) for a Wald distribution.
*
* @param {PositiveNumber} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {Function} function to evaluate the natural logarithm of the cumulative distribution function
*
* @example
* var logcdf = factory( 1.0, 1.0 );
* var y = logcdf( 2.0 );
* // returns ~-0.122
*
* y = logcdf( 0.5 );
* // returns ~-1.008
*/
function factory( mu, lambda ) {
	if (
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( lambda === 0.0 ) {
		return degenerate( mu );
	}
	return logcdf;

	/**
	* Evaluates the natural logarithm of the cumulative distribution function (CDF) of a Wald distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated logCDF
	*
	* @example
	* var y = logcdf( 2.0 );
	* // returns <number>
	*/
	function logcdf( x ) {
		var t1;
		var t2;
		var a;
		var b;
		var z;

		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x <= 0.0 ) {
			return NINF;
		}
		if ( x === PINF ) {
			return 0.0;
		}
		z = sqrt( lambda / x );
		a = ( z * ( ( x / mu ) - 1.0 ) ) / sqrt( 2.0 );
		b = ( z * ( ( x / mu ) + 1.0 ) ) / sqrt( 2.0 );

		// Φ(a) = 0.5 * erfc( -a / √2 )
		t1 = 0.5 * erfc( -a );

		// exp( 2λ/μ ) * erfc( b ) = erfcx( b ) * exp( -a² ), as b² - a² = 2λ/μ; computing via `erfcx` avoids overflow of the exponential term for large `λ/μ`:
		t2 = 0.5 * erfcx( b ) * exp( -a * a );
		return ln( t1 + t2 );
	}
}


// EXPORTS //

module.exports = factory;
